import{_ as e,o as s,c as n,ag as o}from"./chunks/framework.DlQ8ZhpE.js";const u=JSON.parse('{"title":"认证、请求头与请求代理","description":"","frontmatter":{"title":"认证、请求头与请求代理","order":3},"headers":[],"relativePath":"zhHans/docs/features/auth-and-headers.md","filePath":"zhHans/docs/features/auth-and-headers.md"}'),t={name:"zhHans/docs/features/auth-and-headers.md"};function r(c,a,i,d,p,l){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="认证、请求头与请求代理" tabindex="-1">认证、请求头与请求代理 <a class="header-anchor" href="#认证、请求头与请求代理" aria-label="Permalink to &quot;认证、请求头与请求代理&quot;">​</a></h1><h2 id="客户端认证" tabindex="-1">客户端认证 <a class="header-anchor" href="#客户端认证" aria-label="Permalink to &quot;客户端认证&quot;">​</a></h2><p><code>container_registry_single</code>、<code>container_registry_any</code> 和 <code>any_url</code> 模式可以启用客户端认证，访问者需要提供用户名和密码（HTTP Basic Auth）。用户可以直接写在配置文件中，也可以放在外部用户文件里。用户文件支持定期热重载，更新用户列表无需重启 Pavonis。</p><p>容器仓库模式下，访问需要认证的私有上游仓库时，客户端可以在凭据中附带上游仓库的凭据。</p><p>具体写法见 <a href="./../config/auth">ClientAuthConfig</a>。</p><h2 id="请求头管理" tabindex="-1">请求头管理 <a class="header-anchor" href="#请求头管理" aria-label="Permalink to &quot;请求头管理&quot;">​</a></h2><p>Pavonis 向上游转发请求前，默认删除 <code>Via</code>、<code>X-Forwarded-For</code> 等反向代理头部和 Cloudflare 注入的头部，避免上游得知代理链信息。请求头和响应头也可以按需添加、修改或删除。</p><p>默认删除的头部列表和自定义写法见 <a href="./../config/request#headermodificationconfig-请求头修改">RequestConfig</a> 与 <a href="./../config/response">ResponseConfig</a>。</p><h2 id="请求代理" tabindex="-1">请求代理 <a class="header-anchor" href="#请求代理" aria-label="Permalink to &quot;请求代理&quot;">​</a></h2><p>上游请求可以经过一个或多个请求代理，支持 <code>http</code>、<code>https</code>、<code>socks5</code>、<code>socks5h</code>。某个代理连不上时自动切换到下一个，也可以在所有代理都不可用时回退到直连。适合在网络访问受限的环境中部署。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>servers:  proxy1 ── 屏蔽中，跳过</span></span>
<span class="line"><span>          proxy2 ── 连不上，换下一个</span></span>
<span class="line"><span>          proxy3 ── ✓ 经由 proxy3 访问上游</span></span>
<span class="line"><span></span></span>
<span class="line"><span>全部不可用 ──► 启用 direct_fallback ？ 直连上游 : 返回错误</span></span></code></pre></div><p>配置方式见 <a href="./../config/request#requestproxyconfig">RequestConfig</a>。</p>`,12)])])}const f=e(t,[["render",r]]);export{u as __pageData,f as default};
